mapper.select:
SELECT NOTICE_ID, CATEGORY_CODE AS CATEGORY, TITLE, CREATED_AT FROM ( SELECT a.*, ROWNUM AS RN FROM ( SELECT NOTICE_ID, CATEGORY_CODE, TITLE, TRUNC(CREATED_AT) AS CREATED_AT FROM NOTICE WHERE HIDDEN_YN = 'N'
AND CATEGORY_CODE = #{category}
ORDER BY CREATED_AT DESC, NOTICE_ID DESC ) a WHERE ROWNUM <= (#{page} * #{size}) ) WHERE RN > (#{page} - 1) * #{size}
